1	import { policyBasePremium, type Item } from "./price-list.js";
2	
3	export type { Item };
4	
5	export interface Customer {
6	  readonly yearsWithMHPCO: number;
7	  readonly previousContracts: number;
8	}
9	
10	/** MHPCO adds a flat processing fee to every premium, at the very end. */
11	const PROCESSING_FEE_G = 5;
12	
13	/** Every item in a quote is treated as a first insurance: 10 % surcharge. */
14	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
15	
16	const PERCENT = 100;
17	
18	/**
19	 * A policy-wide modifier: it is charged on the policy base premium rather than
20	 * on a single item's base premium. Every item in a quote counts as a first
21	 * insurance regardless of customer history, so the initial assessment
22	 * surcharge is charged on the whole policy base premium.
23	 */
24	function initialAssessmentSurcharge(policyBase: number): number {
25	  return (policyBase * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
26	}
27	
28	/**
29	 * MHPCO rounds every final amount in its own favour: a premium the customer
30	 * owes is rounded up. Only the final amount is rounded; intermediate amounts
31	 * are kept as fractions.
32	 */
33	function roundPremiumInMHPCOFavour(premium: number): number {
34	  return Math.ceil(premium);
35	}
36	
37	export function quote(_customer: Customer, items: readonly Item[]): number {
38	  const policyBase = policyBasePremium(items);
39	  const premium = policyBase + initialAssessmentSurcharge(policyBase) + PROCESSING_FEE_G;
40	  return roundPremiumInMHPCOFavour(premium);
41	}
