1	/**
2	 * The MHPCO price list: what each insured thing costs before any modifier.
3	 *
4	 * This module owns catalogue knowledge only — which item types the office
5	 * recognises and the base premium it charges for them. It deliberately knows
6	 * nothing about surcharges, discounts, the processing fee or rounding: those
7	 * are underwriting policy and change for entirely different reasons.
8	 */
9	
10	export interface Item {
11	  readonly type: string;
12	}
13	
14	/** The MHPCO price list for main items: base premium in G per item type. */
15	const MAIN_ITEM_BASE_PREMIUM_G: Readonly<Record<string, number>> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	};
21	
22	/**
23	 * Components — runes, moonstones and their kin — are not listed individually on
24	 * the main price list. MHPCO charges one uniform rate per component.
25	 */
26	const COMPONENT_BASE_PREMIUM_G = 25;
27	
28	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
29	
30	function isComponent(item: Item): boolean {
31	  return COMPONENT_TYPES.includes(item.type);
32	}
33	
34	/**
35	 * MHPCO offers a building block of exactly 3 alike components — components of
36	 * the same type — at a special base premium instead of the per-component rate.
37	 */
38	const BLOCK_SIZE = 3;
39	const BLOCK_BASE_PREMIUM_G = 60;
40	
41	/** The base premium of a single main item according to the MHPCO price list. */
42	function mainItemBasePremium(item: Item): number {
43	  return MAIN_ITEM_BASE_PREMIUM_G[item.type];
44	}
45	
46	/** The base premium MHPCO charges for a number of alike components. */
47	function alikeComponentsBasePremium(count: number): number {
48	  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM_G : count * COMPONENT_BASE_PREMIUM_G;
49	}
50	
51	function countByType(items: readonly Item[]): Map<string, number> {
52	  const counts = new Map<string, number>();
53	  for (const item of items) {
54	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
55	  }
56	  return counts;
57	}
58	
59	/**
60	 * Components are priced per group of alike components, not per item: MHPCO
61	 * gathers each type together first so that a building block can be recognised.
62	 */
63	function componentsBasePremium(components: readonly Item[]): number {
64	  let total = 0;
65	  for (const count of countByType(components).values()) {
66	    total += alikeComponentsBasePremium(count);
67	  }
68	  return total;
69	}
70	
71	/**
72	 * The sum of the base premiums of all insured items, before any modifier.
73	 *
74	 * Main items are priced one by one straight off the price list; components are
75	 * handed to the component pricing rules as a group, because their price depends
76	 * on how many alike ones the policy covers.
77	 */
78	export function policyBasePremium(items: readonly Item[]): number {
79	  const mainItemsTotal = items
80	    .filter((item) => !isComponent(item))
81	    .reduce((sum, item) => sum + mainItemBasePremium(item), 0);
82	  return mainItemsTotal + componentsBasePremium(items.filter(isComponent));
83	}
