1	import { describe, expect, it } from "vitest";
2	import { quote, type Customer } from "./claim-office.js";
3	
4	/**
5	 * A customer whose history contributes no policy-wide modifier: brand new to
6	 * MHPCO, so neither the loyalty discount nor the follow-up contract discount
7	 * applies. Quotes for this customer show base premiums and the first-insurance
8	 * surcharge on their own.
9	 */
10	const NEWCOMER: Customer = { yearsWithMHPCO: 0, previousContracts: 0 };
11	
12	describe("MHPCO Claim Office", () => {
13	  // --- Quote: processing fee and empty policy ---
14	  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
15	    expect(quote(NEWCOMER, [])).toBe(5);
16	  });
17	
18	  // --- Quote: base premiums per main item type (price list catalogue) ---
19	  it("quotes a single sword with no modifiers -- base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
20	    expect(quote(NEWCOMER, [{ type: "sword" }])).toBe(115);
21	  });
22	  it("quotes a single amulet with no modifiers -- base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
23	    expect(quote(NEWCOMER, [{ type: "amulet" }])).toBe(71);
24	  });
25	  it("quotes a single staff with no modifiers -- base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
26	    expect(quote(NEWCOMER, [{ type: "staff" }])).toBe(93);
27	  });
28	  it("quotes a single potion with no modifiers -- base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
29	    expect(quote(NEWCOMER, [{ type: "potion" }])).toBe(49);
30	  });
31	
32	  // --- Quote: component base premiums and building blocks ---
33	  it("quotes a single rune -- component base premium 25 G", () => {
34	    // 25 base + 2.5 first insurance + 5 fee = 32.5 -> rounded up in MHPCO's favour
35	    expect(quote(NEWCOMER, [{ type: "rune" }])).toBe(33);
36	  });
37	  it("quotes a single moonstone -- component base premium 25 G", () => {
38	    expect(quote(NEWCOMER, [{ type: "moonstone" }])).toBe(33);
39	  });
40	  it("quotes 2 runes -- base premium 50 G (no block)", () => {
41	    // 50 base + 5 first insurance + 5 fee = 60
42	    expect(quote(NEWCOMER, [{ type: "rune" }, { type: "rune" }])).toBe(60);
43	  });
44	  it("quotes 3 runes -- base premium 60 G (block applies)", () => {
45	    // 60 block base + 6 first insurance + 5 fee = 71
46	    const runes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
47	    expect(quote(NEWCOMER, runes)).toBe(71);
48	  });
49	  it("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)", () => {
50	    // 100 base + 10 first insurance + 5 fee = 115
51	    const runes = Array.from({ length: 4 }, () => ({ type: "rune" }));
52	    expect(quote(NEWCOMER, runes)).toBe(115);
53	  });
54	  it("quotes 7 runes -- base premium 175 G (no block; 7 is not exactly 3)", () => {
55	    // 175 base + 17.5 first insurance + 5 fee = 197.5 -> 198 rounded up
56	    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
57	    expect(quote(NEWCOMER, runes)).toBe(198);
58	  });
59	  it("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)", () => {
60	    // 75 base + 7.5 first insurance + 5 fee = 87.5 -> 88 rounded up
61	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
62	    expect(quote(NEWCOMER, items)).toBe(88);
63	  });
64	  it("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks of alike components)", () => {
65	    // 60 + 60 base + 12 first insurance + 5 fee = 137
66	    const items = [
67	      { type: "rune" }, { type: "rune" }, { type: "rune" },
68	      { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
69	    ];
70	    expect(quote(NEWCOMER, items)).toBe(137);
71	  });
72	
73	  // --- Quote: item-specific modifiers ---
74	  it.todo("adds a 50% curse surcharge to the cursed item's base premium");
75	  it.todo("adds a 30% high-enchantment surcharge at enchantment exactly 5");
76	  it.todo("adds no high-enchantment surcharge at enchantment 4");
77	  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
78	  it.todo("applies the curse surcharge only to the cursed item, not the policy total -- cursed sword + plain amulet -> 210 G before policy modifiers and fee");
79	
80	  // --- Quote: policy-wide modifiers ---
81	  it.todo("applies the 20% loyalty discount at exactly 2 years with MHPCO");
82	  it.todo("applies no loyalty discount at 1 year with MHPCO");
83	  it.todo("applies the 10% first-insurance surcharge to every item in every quote, regardless of customer history");
84	  it.todo("applies a 15% follow-up discount on the customer's second quote");
85	  it.todo("applies no follow-up discount on the customer's first quote");
86	  it.todo("adds the 5 G processing fee at the very end, after all other modifiers");
87	
88	  // --- Quote: rounding in MHPCO's favor ---
89	  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
90	  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");
91	
92	  // --- Quote: integration examples ---
93	  it.todo("integration: newcomer (0 years, first contract) with a cursed steel sword enchantment 3 -- premium 165 G");
94	  it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");
95	
96	  // --- Quote: rejection ---
97	  it.todo("rejects a quote containing an unknown item type -- CLI exits non-zero, error on stderr, no results on stdout");
98	
99	  // --- Claim: standard reimbursement and deductible ---
100	  it.todo("pays out full damage minus the 100 G deductible for a steel sword enchantment 3, damage 500 G -- payout 400 G");
101	  it.todo("pays out full damage minus the 100 G deductible for a rune (no enchantment, no material), damage 200 G -- payout 100 G");
102	  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");
103	
104	  // --- Claim: special clauses ---
105	  it.todo("reimburses 50% of damage for enchantment exactly 8 -- dragon sword enchantment 8, damage 1000 G -> payout 400 G");
106	  it.todo("reimburses dragon material fully -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
107	  it.todo("prefers the 50% rule when both clauses apply -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
108	  it.todo("applies only the high-enchantment clause for a steel sword enchantment 9, damage 1000 G -> payout 400 G");
109	
110	  // --- Claim: insurance sum and cap ---
111	  it.todo("caps payout at twice the insurance sum -- single sword policy: insurance sum 1000 G, cap 2000 G");
112	  it.todo("sums insurance values across items -- sword + amulet: insurance sum 1600 G, cap 3200 G");
113	  it.todo("computes insurance sum 2000 G and cap 4000 G for a policy covering two swords");
114	  it.todo("computes insurance sum 1750 G and cap 3500 G for a sword + 3 runes (block affects premium only)");
115	  it.todo("bases the cap on unmodified insurance value -- cursed sword (premium 165 G) still has cap 2000 G");
116	  it.todo("reports remainingCap after a claim -- sword policy, claim 1500 G -> payout 1400 G, remainingCap 600 G");
117	  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G -> payout 600 G, remainingCap 0 G");
118	
119	  // --- Claim: multiple items of the same type ---
120	  it.todo("treats each damage entry of the same itemType as a separate damage with its own deductible -- two swords damaged");
121	  it.todo("rejects a claim with more damage entries of a type than the policy covers -- CLI exits non-zero, error on stderr");
122	
123	  // --- Claim: rounding in MHPCO's favor ---
124	  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");
125	
126	  // --- Claim: rejection ---
127	  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero, error on stderr");
128	  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero, error on stderr");
129	  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero, error on stderr");
130	
131	  // --- CLI: scenario protocol ---
132	  it.todo("CLI reads a JSON scenario from stdin and writes {results: [...]} to stdout in step order");
133	  it.todo("CLI resolves a claim step's policy field to the zero-based index of the earlier quote step");
134	  it.todo("CLI processes the schema example -- amulet quote then 200 G amulet claim -- producing a premium and a payout/remainingCap result");
135	});
