/**
 * MHPCO reads "alike" as "of the same type": two runes and a moonstone are not
 * three alike components, and a policy covering 3 runes and 3 moonstones earns
 * two separate building blocks. Grouping components by type is therefore the
 * office's ruling on what counts as alike, and the sizes of these groups are
 * what the block rule is applied to.
 */
function alikeComponentGroupSizes(components: readonly Item[]): number[] {
  const sizeByType = new Map<string, number>();
  for (const component of components) {
    sizeByType.set(component.type, (sizeByType.get(component.type) ?? 0) + 1);
  }
  return [...sizeByType.values()];
}

/**
 * Components are priced per group of alike components, not per item: MHPCO
 * gathers the alike ones together first so that a building block can be
 * recognised, then prices each group on its own.
 */
function componentsBasePremium(components: readonly Item[]): number {
  return alikeComponentGroupSizes(components).reduce(
    (total, groupSize) => total + alikeComponentsBasePremium(groupSize),
    0,
  );
}

